using System.Text.Json;
var source=Path.GetFullPath(args[0]); var root=Path.GetFullPath(args[1]);
Directory.CreateDirectory(Path.Combine(root,"data"));
foreach(var f in new[]{"rfq-intakes.json","rfq-lanes.json"}) File.Copy(Path.Combine(source,"data",f),Path.Combine(root,"data",f),true);
var json=new JsonSerializerOptions(JsonSerializerDefaults.Web){WriteIndented=true};
var store=new SimRfqIntakeStore(root);
var record=(SimRfqIntakeRecord)(await store.ReadAsync("RFQI-SIM-0043"))!;var p=record.OrderIntake!;
var folder=Path.Combine("intake-documents",record.RequestCorrelationId);Directory.CreateDirectory(Path.Combine(root,folder));
foreach(var e in p.PoEvidence) foreach(var suffix in new[]{".bin",".json"}) File.Copy(Path.Combine(source,folder,e.Document.DocumentId+suffix),Path.Combine(root,folder,e.Document.DocumentId+suffix),true);
var persona=new SimPersona("preview-test","preview-test","Preview Reviewer","ACTIVE",[],[],true,"test");
var request=new SimOrderSaveRequest(Guid.NewGuid().ToString(),record.RequestCorrelationId,record.IntakeId,p.Revision,record.Customer,p.PoNumber,p.Facts,p.PreviouslyQuoted,p.Quote?.Reference,p.Questionnaire,p.PoEvidence.Select(e=>e.Document).ToArray(),p.WizardStep,false,p.TechnicalSource?.Choice,[],"review",true,3,p.ContractDates?.PoDateVerification is not null,p.ContractDates?.DueDateReview is {} d ? new(d.Disposition,d.Note):null);
int count=0;void Check(bool b,string m){if(!b)throw new Exception(m);Console.WriteLine("PASS "+m);count++;}
var before=File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json"));var lanes=File.ReadAllText(Path.Combine(root,"data","rfq-lanes.json"));
var view=await store.PreviewContractReview(request,persona);
Check(view.Title=="NEW ORDER FINAL REVIEW - DRAFT" && !view.Acknowledged,"draft not accepted or acknowledged by preview");
Check(view.TechnicalDocuments.Length==2&&view.TechnicalDocuments.Any(d=>d.Type=="BOM")&&view.TechnicalDocuments.Any(d=>d.Type=="Technical Drawing"),"two quoted document types and existing view links");
Check(view.PoDocuments.Single().Url!.StartsWith("/api/sim/new-orders/RFQI-SIM-0043/documents/"),"existing verified PO retrieval path");
Check(view.Sections.Single(s=>s.Title=="PO / Quote Review").Fields.Any(f=>f.Label=="Core quote comparison"&&f.Value=="MATCH"),"server core comparison matches");
Check(view.Sections.Single(s=>s.Title=="Delivery").Fields.Any(f=>f.Value.StartsWith("10/13/2026")),"date-only reference is October 13");
Check(view.Sections.Single(s=>s.Title=="Delivery").Fields.Any(f=>f.Label=="Customer Due Date"&&f.Value=="10/14/2026"),"manual due date retained");
var comparison=await store.PreviewOrder(new(record.Customer,p.Facts,p.PreviouslyQuoted,p.Quote?.Reference));
SimContractReviewProjection Build(SimOrderSaveRequest r)=>SimRfqIntakeStore.BuildContractReview(r,comparison,view.PoDocuments,view.TechnicalDocuments,persona,new DateTimeOffset(2026,9,23,12,0,0,TimeSpan.Zero));
var acknowledged=Build(request with{Questionnaire=p.Questionnaire! with{RequirementsIdentifiedOnAttachedDocument=true}});
Check(acknowledged.Reviewer=="Preview Reviewer"&&acknowledged.ReviewedDate.Contains("not recorded"),"acknowledgment preview actor is authenticated reviewer, never fabricated audit history");
var relative=Build(request with{Facts=p.Facts with{RequestedDelivery="3 weeks after acknowledgment"}});
Check(!relative.Attention.Any(a=>a.Contains("no fixed date")),"relative lead alone is not a contradiction");
var conflict=Build(request with{Facts=p.Facts with{RequestedDelivery="no fixed calendar delivery date"}});
Check(!conflict.Attention.Any(a=>a.Contains("no fixed date")),"explicit accepted reviewed due date governs while original wording is retained");
var unreviewed=Build(request with{DueDateDecision=null,Facts=p.Facts with{RequestedDelivery="no fixed calendar delivery date"}});
Check(unreviewed.Attention.Any(a=>a.Contains("no fixed date")),"unreviewed conflicting date still requires attention");
var legacy=Build(request with{Questionnaire=p.Questionnaire! with{PoFlowdowns="Q1",AdditionalContractQualityRequirements="Inspection",SpecialRequirements="Prior note",OtherCustomerRequirements="Current note"}});
Check(legacy.Sections.Single(s=>s.Title=="Other Customer Requirements").Fields.Length==4,"legacy and current requirements retained separately");
try{await store.PreviewContractReview(request with{ExpectedRevision=p.Revision+1},persona);throw new Exception("stale accepted");}catch(SimRfqIntakeProblem e){Check(e.Code=="ORDER_STALE","stale preview rejected");}
Check(File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json"))==before&&File.ReadAllText(Path.Combine(root,"data","rfq-lanes.json"))==lanes,"preview leaves all business data byte-identical");
Directory.CreateDirectory(Path.GetFullPath(args[2]));
await File.WriteAllTextAsync(Path.Combine(args[2],"projection.json"),JsonSerializer.Serialize(view,json));
await File.WriteAllTextAsync(Path.Combine(args[2],"request.json"),JsonSerializer.Serialize(request,json));
var pdf=await SimQuotationPdf.RenderDocument(view,"sim_contract_review_pdf.py");await File.WriteAllBytesAsync(Path.Combine(args[2],"RFQI-SIM-0043-contract-review-preview.pdf"),pdf);
Check(System.Text.Encoding.ASCII.GetString(pdf,0,5)=="%PDF-","shared projection renders PDF");
Console.WriteLine($"{count} checks passed");
